function catchesBug(good, buggy, input) {
  return good(input) !== buggy(input);
}

function firstCatchingInput(good, buggy, inputs) {
  for (const input of inputs) {
    if (good(input) !== buggy(input)) return input;
  }
  return null;
}

function countCatching(good, buggy, inputs) {
  let count = 0;
  for (const input of inputs) {
    if (good(input) !== buggy(input)) count += 1;
  }
  return count;
}

function mutantSurvives(good, mutant, inputs) {
  for (const input of inputs) {
    if (good(input) !== mutant(input)) return false;
  }
  return true;
}

function matchesAll(fn, cases) {
  for (const [input, expected] of cases) {
    if (fn(input) !== expected) return false;
  }
  return true;
}

