function assertionIsBlind(check, good, buggy, input) {
  return check(good(input)) === check(buggy(input));
}

function failingInputs(fn, cases) {
  const failing = [];
  for (const [input, expected] of cases) {
    if (fn(input) !== expected) failing.push(input);
  }
  return failing;
}

function survivingMutants(good, mutants, inputs) {
  const survivors = [];
  mutants.forEach((mutant, index) => {
    const caught = inputs.some((input) => good(input) !== mutant(input));
    if (!caught) survivors.push(index);
  });
  return survivors;
}

function suiteCatchesAll(good, mutants, inputs) {
  return mutants.every((mutant) =>
    inputs.some((input) => good(input) !== mutant(input)),
  );
}

function inputsCatching(good, mutant, inputs) {
  return inputs.filter((input) => good(input) !== mutant(input));
}

function boundaryCases(thresholds) {
  const values = new Set();
  for (const t of thresholds) {
    values.add(t - 1);
    values.add(t);
  }
  return [...values].sort((a, b) => a - b);
}
